def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set(); comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] and (r,c) not in seen:
                q=deque([(r,c)]); seen.add((r,c)); pts=[]
                while q:
                    y,x=q.popleft(); pts.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        z=(y+dy,x+dx)
                        if 0<=z[0]<h and 0<=z[1]<w and grid[z[0]][z[1]] and z not in seen:
                            seen.add(z); q.append(z)
                comps.append(pts)
    if len(comps)<2: return [[8]]
    comps.sort(key=len, reverse=True)
    def crop(pts):
        a=min(y for y,x in pts); b=max(y for y,x in pts); c=min(x for y,x in pts); d=max(x for y,x in pts)
        return [[grid[y][x] for x in range(c,d+1)] for y in range(a,b+1)]
    A,B=map(crop,comps[:2])
    # Compare the two figures under the possible quarter-turn orientations.
    variants=[]
    for k in range(4):
        b=[list(row) for row in B]
        for _ in range(k): b=[list(row) for row in zip(*b[::-1])]
        for flip in (False,True):
            bb=[row[::-1] for row in b] if flip else b
            hh=min(len(A),len(bb)); ww=min(len(A[0]),len(bb[0]))
            score=sum(A[y][x]!=bb[y][x] for y in range(hh) for x in range(ww))
            variants.append((score,hh,ww,bb))
    _,hh,ww,B= min(variants,key=lambda z:z[0])
    diff=[[8 if A[y][x]!=B[y][x] else 0 for x in range(ww)] for y in range(hh)]
    rs=[y for y in range(hh) if any(diff[y])]; cs=[x for x in range(ww) if any(diff[y][x] for y in range(hh))]
    if not rs or not cs: return [[0]]
    return [[diff[y][x] for x in range(cs[0],cs[-1]+1)] for y in range(rs[0],rs[-1]+1)]
